<?php if($focus['status']!=='paid'): ?><section class="panel editor-panel"><div class="panel-head"><div><h3>Pagar fatura</h3><p>O pagamento será debitado da conta, sem gerar uma segunda despesa.</p></div></div><form method="post" action="/invoices/pay" class="inline-payment"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="invoice_id" value="<?=(int)$focus['id']?>"><label>Conta<select name="account_id" required><?php foreach($accounts as $account): ?><option value="<?=(int)$account['id']?>" <?=((int)($focus['payment_account_id']??0)===(int)$account['id'])?'selected':''?>><?=e($account['name'])?></option><?php endforeach; ?></select></label><button class="button primary">Pagar <?=money($total)?></button></form></section><?php endif; ?>
